from __future__ import annotations
from qfap_adds.qfap_adds.project_management.report_link_titles import finalize_report_result
from frappe.utils.safe_exec import safe_exec
REPORT_SCRIPT='# Project Beneficiary Reach and Disaggregation v1.3\r\n# Frappe / ERPNext 16 Custom Script Report - Safe Execution\r\n\r\nfilters = filters or {}\r\nview = filters.get("view") or "Executive Reach"\r\nprojects_filter = filters.get("projects") or []\r\nstatuses_filter = filters.get("plan_statuses") or []\r\ntracking_filter = filters.get("tracking_modes") or []\r\nquality_filter = filters.get("data_quality") or []\r\nreach_filter = filters.get("reach_types") or []\r\nunits_filter = filters.get("primary_units") or []\r\ngovernorates_filter = filters.get("governorates") or []\r\ndistricts_filter = filters.get("districts") or []\r\nsectors_filter = filters.get("sectors") or []\r\npartners_filter = filters.get("implementing_partners") or []\r\ndonors_filter = filters.get("donors") or []\r\nfrom_date = filters.get("from_date")\r\nto_date = filters.get("to_date")\r\nbelow_target_only = int(filters.get("below_target_only") or 0)\r\nmissing_updates_only = int(filters.get("missing_updates_only") or 0)\r\nquality_issues_only = int(filters.get("quality_issues_only") or 0)\r\ninclude_drafts = int(filters.get("include_drafts") or 0)\r\ninclude_cancelled = int(filters.get("include_cancelled") or 0)\r\n\r\n# Bootstrap contextual dimensions from Projects, even before a Beneficiary Plan exists.\r\nproject_meta = frappe.get_meta("Project")\r\neligible_project_filters = {}\r\nif project_meta.has_field("custom_beneficiary_tracking_required"):\r\n    eligible_project_filters["custom_beneficiary_tracking_required"] = 1\r\nif project_meta.has_field("custom_beneficiary_tracking_mode"):\r\n    eligible_project_filters["custom_beneficiary_tracking_mode"] = ["!=", "Not Applicable"]\r\nif projects_filter:\r\n    eligible_project_filters["name"] = ["in", projects_filter]\r\neligible_project_fields = ["name","project_name","company","expected_start_date","expected_end_date"]\r\nfor fn in ["custom_project_stage","custom_calculated_project_health","custom_project_manager","custom_beneficiary_tracking_required","custom_beneficiary_tracking_mode"]:\r\n    if project_meta.has_field(fn): eligible_project_fields.append(fn)\r\neligible_projects = frappe.get_all("Project", filters=eligible_project_filters, fields=eligible_project_fields, order_by="project_name asc", limit_page_length=0)\r\neligible_project_names = []\r\neligible_project_map = {}\r\nfor ep in eligible_projects:\r\n    eligible_project_names.append(ep.name)\r\n    eligible_project_map[ep.name] = ep\r\n\r\nplan_filters = []\r\nif not include_cancelled:\r\n    plan_filters.append(["Project Beneficiary Plan", "docstatus", "<", 2])\r\nif not include_drafts:\r\n    plan_filters.append(["Project Beneficiary Plan", "docstatus", "=", 1])\r\nif eligible_project_names:\r\n    plan_filters.append(["Project Beneficiary Plan", "project", "in", eligible_project_names])\r\nelif projects_filter:\r\n    plan_filters.append(["Project Beneficiary Plan", "project", "in", projects_filter])\r\nif statuses_filter:\r\n    plan_filters.append(["Project Beneficiary Plan", "status", "in", statuses_filter])\r\nif tracking_filter:\r\n    plan_filters.append(["Project Beneficiary Plan", "tracking_mode", "in", tracking_filter])\r\n\r\nplans = frappe.get_all(\r\n    "Project Beneficiary Plan",\r\n    filters=plan_filters,\r\n    fields=["name","project","project_name","tracking_mode","status","docstatus",\r\n            "planned_individuals_total","actual_individuals_total","individual_achievement_total",\r\n            "planned_households_total","actual_households_total","household_achievement_total",\r\n            "planned_pwd_total","actual_pwd_total","actual_update_frequency","last_actual_update",\r\n            "actuals_finalized","actuals_finalized_on","actuals_finalized_by","modified","remarks"],\r\n    order_by="project asc, modified desc",\r\n    limit_page_length=0\r\n)\r\n\r\n# Keep one current active plan per project and flag duplicates.\r\nplan_by_project = {}\r\nactive_counts = {}\r\nfor p in plans:\r\n    active_counts[p.project] = active_counts.get(p.project, 0) + 1\r\n    if not plan_by_project.get(p.project):\r\n        plan_by_project[p.project] = p\r\n\r\nproject_names = []\r\nfor project_name in eligible_project_names:\r\n    if project_name not in project_names: project_names.append(project_name)\r\nfor project_name in plan_by_project:\r\n    if project_name not in project_names: project_names.append(project_name)\r\n\r\n# Context dimensions are derived only from records linked to the selected report projects.\r\nproject_donors = {}\r\nproject_donor_values = {}\r\nproject_sector_values = {}\r\nproject_partner_values = {}\r\nif project_names:\r\n    funding_rows = frappe.get_all("Project Funding Source", filters={"parent":["in",project_names],"parenttype":"Project"}, fields=["parent","donor","is_primary_donor"], limit_page_length=0)\r\n    for x in funding_rows:\r\n        if not project_donor_values.get(x.parent): project_donor_values[x.parent] = []\r\n        if x.donor and x.donor not in project_donor_values[x.parent]: project_donor_values[x.parent].append(x.donor)\r\n    sector_rows = frappe.get_all("Project Sector", filters={"parent":["in",project_names],"parenttype":"Project"}, fields=["name","parent","sector"], limit_page_length=0)\r\n    for x in sector_rows:\r\n        if not project_sector_values.get(x.parent): project_sector_values[x.parent] = []\r\n        if x.sector and x.sector not in project_sector_values[x.parent]: project_sector_values[x.parent].append(x.sector)\r\n    partner_rows = frappe.get_all("Project Partner", filters={"parent":["in",project_names],"parenttype":"Project"}, fields=["parent","partner"], limit_page_length=0)\r\n    for x in partner_rows:\r\n        if not project_partner_values.get(x.parent): project_partner_values[x.parent] = []\r\n        if x.partner and x.partner not in project_partner_values[x.parent]: project_partner_values[x.parent].append(x.partner)\r\n\r\nproject_governorate_context = {}\r\nproject_district_context = {}\r\nif project_names:\r\n    location_rows = frappe.get_all("Project Geographic Location", filters={"parent":["in",project_names],"parenttype":"Project"}, fields=["parent","governorate","district"], limit_page_length=0)\r\n    for x in location_rows:\r\n        if not project_governorate_context.get(x.parent): project_governorate_context[x.parent] = []\r\n        if not project_district_context.get(x.parent): project_district_context[x.parent] = []\r\n        if x.governorate and x.governorate not in project_governorate_context[x.parent]: project_governorate_context[x.parent].append(x.governorate)\r\n        if x.district and x.district not in project_district_context[x.parent]: project_district_context[x.parent].append(x.district)\r\n\r\n# Donor, sector, partner and project-location filters work before a Beneficiary Plan exists.\r\nif donors_filter or sectors_filter or partners_filter or governorates_filter or districts_filter:\r\n    allowed_projects = []\r\n    for project_name in project_names:\r\n        donor_ok = not donors_filter\r\n        sector_ok = not sectors_filter\r\n        partner_ok = not partners_filter\r\n        governorate_ok = not governorates_filter\r\n        district_ok = not districts_filter\r\n        if donors_filter:\r\n            for value in project_donor_values.get(project_name) or []:\r\n                if value in donors_filter: donor_ok = True\r\n        if sectors_filter:\r\n            for value in project_sector_values.get(project_name) or []:\r\n                if value in sectors_filter: sector_ok = True\r\n        if partners_filter:\r\n            for value in project_partner_values.get(project_name) or []:\r\n                if value in partners_filter: partner_ok = True\r\n        if governorates_filter:\r\n            for value in project_governorate_context.get(project_name) or []:\r\n                if value in governorates_filter: governorate_ok = True\r\n        if districts_filter:\r\n            for value in project_district_context.get(project_name) or []:\r\n                if value in districts_filter: district_ok = True\r\n        if donor_ok and sector_ok and partner_ok and governorate_ok and district_ok: allowed_projects.append(project_name)\r\n    filtered_plan_map = {}\r\n    for project_name in allowed_projects:\r\n        if plan_by_project.get(project_name): filtered_plan_map[project_name] = plan_by_project[project_name]\r\n    plan_by_project = filtered_plan_map\r\n    project_names = allowed_projects\r\n\r\nproject_map = {}\r\nfor project_name in eligible_project_map:\r\n    project_map[project_name] = eligible_project_map[project_name]\r\nproject_meta = frappe.get_meta("Project")\r\nproject_fields = ["name","project_name","company","expected_start_date","expected_end_date"]\r\nfor fn in ["custom_project_stage","custom_calculated_project_health","custom_project_manager",\r\n           "custom_beneficiary_tracking_required","custom_beneficiary_tracking_mode"]:\r\n    if project_meta.has_field(fn):\r\n        project_fields.append(fn)\r\nif project_names:\r\n    project_rows = frappe.get_all("Project", filters={"name":["in",project_names]}, fields=project_fields, limit_page_length=0)\r\n    for p in project_rows:\r\n        project_map[p.name] = p\r\n\r\n# Child rows belong to submitted plans; cancelled parents are already excluded.\r\nbreakdown_rows = []\r\nplan_names = []\r\nfor project_name in plan_by_project:\r\n    plan_names.append(plan_by_project[project_name].name)\r\nif plan_names:\r\n    breakdown_filters = [["Beneficiary Breakdown","parent","in",plan_names],\r\n                         ["Beneficiary Breakdown","parenttype","=","Project Beneficiary Plan"],\r\n                         ["Beneficiary Breakdown","parentfield","=","beneficiary_breakdown"]]\r\n    if quality_filter:\r\n        breakdown_filters.append(["Beneficiary Breakdown","data_quality","in",quality_filter])\r\n    if reach_filter:\r\n        breakdown_filters.append(["Beneficiary Breakdown","reach_type","in",reach_filter])\r\n    if units_filter:\r\n        breakdown_filters.append(["Beneficiary Breakdown","primary_unit","in",units_filter])\r\n    if governorates_filter:\r\n        breakdown_filters.append(["Beneficiary Breakdown","governorate","in",governorates_filter])\r\n    if districts_filter:\r\n        breakdown_filters.append(["Beneficiary Breakdown","district","in",districts_filter])\r\n    if partners_filter:\r\n        breakdown_filters.append(["Beneficiary Breakdown","implementing_partner","in",partners_filter])\r\n    if from_date:\r\n        breakdown_filters.append(["Beneficiary Breakdown","period_to",">=",from_date])\r\n    if to_date:\r\n        breakdown_filters.append(["Beneficiary Breakdown","period_from","<=",to_date])\r\n    breakdown_rows = frappe.get_all(\r\n        "Beneficiary Breakdown", filters=breakdown_filters,\r\n        fields=["name","parent","idx","row_code","project_objective","project_result","project_indicator",\r\n                "project_activity","sector","sub_sector","implementing_partner","geographic_location",\r\n                "governorate","district","period_from","period_to","reporting_period","activity_status",\r\n                "tracking_method","reach_type","counting_method","primary_unit","other_unit_label",\r\n                "household_relationship","data_quality","data_source","displacement_status","population_group",\r\n                "disaggregation_level","beneficiary_category","planned_women","planned_men","planned_girls",\r\n                "planned_boys","planned_individuals","planned_households","planned_other_units","planned_pwd",\r\n                "planned_female_headed_hh","planned_older_persons","actual_women","actual_men","actual_girls",\r\n                "actual_boys","actual_individuals","actual_households","actual_other_units","actual_pwd",\r\n                "actual_female_headed_hh","actual_older_persons","individual_variance","individual_achievement",\r\n                "household_variance","household_achievement","reconciliation_variance","variance_explanation","notes"],\r\n        order_by="parent asc, period_from asc, idx asc", limit_page_length=0\r\n    )\r\n\r\nplan_name_map = {}\r\nfor project_name in plan_by_project:\r\n    plan_name_map[plan_by_project[project_name].name] = project_name\r\n\r\nproject_governorate_values = {}\r\nproject_district_values = {}\r\nfor r in breakdown_rows:\r\n    project_name = plan_name_map.get(r.parent) or ""\r\n    if project_name:\r\n        if not project_governorate_values.get(project_name): project_governorate_values[project_name] = []\r\n        if not project_district_values.get(project_name): project_district_values[project_name] = []\r\n        if r.governorate and r.governorate not in project_governorate_values[project_name]: project_governorate_values[project_name].append(r.governorate)\r\n        if r.district and r.district not in project_district_values[project_name]: project_district_values[project_name].append(r.district)\r\n\r\nsector_name_map = {}\r\nsector_link_ids = []\r\nfor r in breakdown_rows:\r\n    if r.sector and r.sector not in sector_link_ids: sector_link_ids.append(r.sector)\r\nif sector_link_ids:\r\n    for x in frappe.get_all("Project Sector", filters={"name":["in",sector_link_ids]}, fields=["name","sector"], limit_page_length=0):\r\n        sector_name_map[x.name] = x.sector or x.name\r\nif sectors_filter:\r\n    filtered_breakdown = []\r\n    for r in breakdown_rows:\r\n        if sector_name_map.get(r.sector) in sectors_filter: filtered_breakdown.append(r)\r\n    breakdown_rows = filtered_breakdown\r\n\r\n# Descriptive titles.\r\nresult_titles = {}\r\nresult_ids = []\r\nactivity_titles = {}\r\nactivity_ids = []\r\nindicator_titles = {}\r\nindicator_ids = []\r\nfor r in breakdown_rows:\r\n    if r.project_result and r.project_result not in result_ids: result_ids.append(r.project_result)\r\n    if r.project_activity and r.project_activity not in activity_ids: activity_ids.append(r.project_activity)\r\n    if r.project_indicator and r.project_indicator not in indicator_ids: indicator_ids.append(r.project_indicator)\r\nif result_ids:\r\n    for x in frappe.get_all("Project Result", filters={"name":["in",result_ids]}, fields=["name","result_code","result_statement"], limit_page_length=0):\r\n        result_titles[x.name] = ((x.result_code or "") + " - " + (x.result_statement or x.name)).strip(" -")\r\nif activity_ids:\r\n    for x in frappe.get_all("Project Workplan Activity", filters={"name":["in",activity_ids]}, fields=["name","activity_code","activity_name"], limit_page_length=0):\r\n        activity_titles[x.name] = ((x.activity_code or "") + " - " + (x.activity_name or x.name)).strip(" -")\r\nif indicator_ids:\r\n    for x in frappe.get_all("Project Indicator", filters={"name":["in",indicator_ids]}, fields=["name","indicator_code","indicator_name"], limit_page_length=0):\r\n        indicator_titles[x.name] = ((x.indicator_code or "") + " - " + (x.indicator_name or x.name)).strip(" -")\r\n\r\n# Validate detail rows and prepare per-plan totals from the same filtered detail set.\r\ndetail_totals = {}\r\ndetail_quality = {}\r\nseen_keys = []\r\ndetail_data = []\r\nfor r in breakdown_rows:\r\n    project_name = plan_name_map.get(r.parent) or ""\r\n    pi = int(r.planned_individuals or 0)\r\n    ai = int(r.actual_individuals or 0)\r\n    ph = int(r.planned_households or 0)\r\n    ah = int(r.actual_households or 0)\r\n    ppwd = int(r.planned_pwd or 0)\r\n    apwd = int(r.actual_pwd or 0)\r\n    calc_pi = int(r.planned_women or 0)+int(r.planned_men or 0)+int(r.planned_girls or 0)+int(r.planned_boys or 0)\r\n    calc_ai = int(r.actual_women or 0)+int(r.actual_men or 0)+int(r.actual_girls or 0)+int(r.actual_boys or 0)\r\n    flags = []\r\n    key = "::".join([str(r.parent or ""),str(r.row_code or "")])\r\n    if key in seen_keys: flags.append("Duplicate Row Code")\r\n    else: seen_keys.append(key)\r\n    if pi != calc_pi or ai != calc_ai: flags.append("Sex/Age Reconciliation")\r\n    if int(r.reconciliation_variance or 0) != 0: flags.append("Reconciliation Variance")\r\n    if ppwd > pi and pi > 0: flags.append("Planned PWD Exceeds Individuals")\r\n    if apwd > ai and ai > 0: flags.append("Actual PWD Exceeds Individuals")\r\n    if ai > 0 and not r.data_source: flags.append("Missing Data Source")\r\n    if ai > 0 and r.data_quality in ["Not Yet Available","Projected"]: flags.append("Actual with Weak Quality")\r\n    if r.counting_method != "Unique Persons" and ai > 0: flags.append("Not Unique Persons")\r\n    if r.reach_type == "Indirect" and r.counting_method == "Unique Persons": flags.append("Review Indirect Unique Count")\r\n    if r.primary_unit == "Other" and not r.other_unit_label: flags.append("Missing Other Unit Label")\r\n    if r.period_from and r.period_to and str(r.period_from) > str(r.period_to): flags.append("Invalid Period")\r\n    quality_status = "Issue" if flags else (r.data_quality or "Not Yet Available")\r\n    detail_quality[r.name] = {"status":quality_status,"flags":", ".join(flags)}\r\n    if not detail_totals.get(r.parent):\r\n        detail_totals[r.parent] = {"pi":0,"ai":0,"ph":0,"ah":0,"ppwd":0,"apwd":0,"issues":0}\r\n    t = detail_totals[r.parent]\r\n    t["pi"] = t.get("pi",0)+pi; t["ai"] = t.get("ai",0)+ai\r\n    t["ph"] = t.get("ph",0)+ph; t["ah"] = t.get("ah",0)+ah\r\n    t["ppwd"] = t.get("ppwd",0)+ppwd; t["apwd"] = t.get("apwd",0)+apwd\r\n    if flags: t["issues"] = t.get("issues",0)+1\r\n    row = {"project":project_name,"plan":r.parent,"row_code":r.row_code,"project_result":r.project_result,\r\n           "result_title":result_titles.get(r.project_result) or r.project_result or "",\r\n           "project_indicator":r.project_indicator,"indicator_title":indicator_titles.get(r.project_indicator) or r.project_indicator or "",\r\n           "project_activity":r.project_activity,"activity_title":activity_titles.get(r.project_activity) or r.project_activity or "",\r\n           "sector":sector_name_map.get(r.sector) or r.sector,"sub_sector":r.sub_sector,"implementing_partner":r.implementing_partner,\r\n           "donors":", ".join(project_donor_values.get(project_name) or []),\r\n           "geographic_location":r.geographic_location,"governorate":r.governorate,"district":r.district,\r\n           "period_from":r.period_from,"period_to":r.period_to,"reporting_period":r.reporting_period,\r\n           "activity_status":r.activity_status,"tracking_method":r.tracking_method,"reach_type":r.reach_type,\r\n           "counting_method":r.counting_method,"primary_unit":r.primary_unit,"other_unit_label":r.other_unit_label,\r\n           "household_relationship":r.household_relationship,"data_quality":r.data_quality,"data_source":r.data_source,\r\n           "displacement_status":r.displacement_status,"population_group":r.population_group,\r\n           "beneficiary_category":r.beneficiary_category,"disaggregation_level":r.disaggregation_level,\r\n           "planned_women":r.planned_women,"planned_men":r.planned_men,"planned_girls":r.planned_girls,"planned_boys":r.planned_boys,\r\n           "planned_individuals":pi,"planned_households":ph,"planned_other_units":r.planned_other_units,"planned_pwd":ppwd,\r\n           "planned_female_headed_hh":r.planned_female_headed_hh,"planned_older_persons":r.planned_older_persons,\r\n           "actual_women":r.actual_women,"actual_men":r.actual_men,"actual_girls":r.actual_girls,"actual_boys":r.actual_boys,\r\n           "actual_individuals":ai,"actual_households":ah,"actual_other_units":r.actual_other_units,"actual_pwd":apwd,\r\n           "actual_female_headed_hh":r.actual_female_headed_hh,"actual_older_persons":r.actual_older_persons,\r\n           "individual_variance":ai-pi,"individual_achievement":(float(ai)*100.0/float(pi)) if pi>0 else 0,\r\n           "household_variance":ah-ph,"household_achievement":(float(ah)*100.0/float(ph)) if ph>0 else 0,\r\n           "variance_explanation":r.variance_explanation,"notes":r.notes,"data_quality_status":quality_status,\r\n           "quality_flags":", ".join(flags)}\r\n    detail_data.append(row)\r\n\r\n# Add context-only rows for beneficiary-tracked Projects without a submitted/current Plan.\r\n# These rows make contextual filter options available before beneficiary records are created.\r\nfor project_name in project_names:\r\n    if plan_by_project.get(project_name):\r\n        continue\r\n    context_row = {\r\n        "project":project_name,"project_name":(project_map.get(project_name) or {}).get("project_name") or project_name,\r\n        "plan":"","row_code":"","reporting_period":"","period_from":None,"period_to":None,\r\n        "sector":", ".join(project_sector_values.get(project_name) or []),\r\n        "donors":", ".join(project_donor_values.get(project_name) or []),\r\n        "implementing_partner":", ".join(project_partner_values.get(project_name) or []),\r\n        "governorate":", ".join(project_governorate_context.get(project_name) or []),\r\n        "district":", ".join(project_district_context.get(project_name) or []),\r\n        "planned_individuals":0,"actual_individuals":0,"individual_achievement":0,\r\n        "planned_households":0,"actual_households":0,"household_achievement":0,\r\n        "data_quality":"Not Yet Available","data_quality_status":"Not Planned",\r\n        "quality_flags":"Beneficiary Plan Not Available","reach_status":"Not Planned",\r\n        "beneficiary_attention":"Review Required"\r\n    }\r\n    detail_data.append(context_row)\r\n\r\n# Executive rows use authoritative submitted-plan totals unless a detail dimension/date filter is active.\r\n# In that case, totals are recalculated from the matching Breakdown rows so filtering is numerically meaningful.\r\ndetail_scope_active = bool(governorates_filter or districts_filter or sectors_filter or partners_filter or quality_filter or reach_filter or units_filter or from_date or to_date)\r\nexecutive_data = []\r\nfor project_name in plan_by_project:\r\n    p = plan_by_project[project_name]\r\n    pr = project_map.get(project_name) or {}\r\n    t = detail_totals.get(p.name) or {"pi":0,"ai":0,"ph":0,"ah":0,"ppwd":0,"apwd":0,"issues":0}\r\n    if detail_scope_active:\r\n        pi = int(t.get("pi",0)); ai = int(t.get("ai",0))\r\n        ph = int(t.get("ph",0)); ah = int(t.get("ah",0))\r\n        ppwd = int(t.get("ppwd",0)); apwd = int(t.get("apwd",0))\r\n    else:\r\n        pi = int(p.planned_individuals_total or 0); ai = int(p.actual_individuals_total or 0)\r\n        ph = int(p.planned_households_total or 0); ah = int(p.actual_households_total or 0)\r\n        ppwd = int(p.planned_pwd_total or 0); apwd = int(p.actual_pwd_total or 0)\r\n    flags = []\r\n    if active_counts.get(project_name,0)>1: flags.append("Multiple Active Plans")\r\n    if not detail_scope_active and (pi != t.get("pi",0) or ai != t.get("ai",0) or ph != t.get("ph",0) or ah != t.get("ah",0)): flags.append("Plan/Detail Reconciliation")\r\n    if ai>0 and not p.last_actual_update: flags.append("Missing Actual Update Date")\r\n    if int(p.actuals_finalized or 0)==1 and (not p.actuals_finalized_on or not p.actuals_finalized_by): flags.append("Incomplete Finalization Audit")\r\n    if p.status=="Actuals Finalized" and int(p.actuals_finalized or 0)!=1: flags.append("Finalization Status Mismatch")\r\n    if t.get("issues",0)>0: flags.append(str(t.get("issues",0))+" Detail Quality Issue(s)")\r\n    achievement = float(ai)*100.0/float(pi) if pi>0 else 0\r\n    reach_status = "Not Planned"\r\n    if pi>0:\r\n        if ai==0: reach_status="Not Reported"\r\n        elif achievement<90: reach_status="Below Target"\r\n        elif achievement<100: reach_status="On Track"\r\n        elif achievement<=110: reach_status="Target Achieved"\r\n        else: reach_status="Exceeded Target"\r\n    attention = "Review Required" if flags or reach_status in ["Not Planned","Not Reported","Below Target","Exceeded Target"] else "No Immediate Issue"\r\n    row = {"project":project_name,"project_name":p.project_name,"project_stage":pr.get("custom_project_stage") or "",\r\n           "project_health":pr.get("custom_calculated_project_health") or "","project_manager":pr.get("custom_project_manager") or "",\r\n           "plan":p.name,"plan_status":p.status,"docstatus":p.docstatus,"tracking_mode":p.tracking_mode,\r\n           "donors":", ".join(project_donor_values.get(project_name) or []),\r\n           "sectors":", ".join(project_sector_values.get(project_name) or []),\r\n           "implementing_partners":", ".join(project_partner_values.get(project_name) or []),\r\n           "governorate":", ".join(project_governorate_values.get(project_name) or []),\r\n           "district":", ".join(project_district_values.get(project_name) or []),\r\n           "planned_individuals":pi,"actual_individuals":ai,"individual_variance":ai-pi,"individual_achievement":achievement,\r\n           "planned_households":ph,"actual_households":ah,"household_variance":ah-ph,\r\n           "household_achievement":(float(ah)*100.0/float(ph)) if ph>0 else 0,\r\n           "planned_pwd":ppwd,"actual_pwd":apwd,"pwd_achievement":(float(apwd)*100.0/float(ppwd)) if ppwd>0 else 0,\r\n           "actual_update_frequency":p.actual_update_frequency,"last_actual_update":p.last_actual_update,\r\n           "actuals_finalized":p.actuals_finalized,"actuals_finalized_on":p.actuals_finalized_on,\r\n           "reach_status":reach_status,"data_quality_status":"Issue" if flags else "Valid",\r\n           "quality_flags":", ".join(flags),"beneficiary_attention":attention,"remarks":p.remarks}\r\n    if detail_scope_active and not detail_totals.get(p.name): continue\r\n    if below_target_only and reach_status!="Below Target": continue\r\n    if missing_updates_only and p.last_actual_update: continue\r\n    if quality_issues_only and not flags: continue\r\n    executive_data.append(row)\r\n\r\n# Ensure Executive Reach also lists tracked Projects with no Beneficiary Plan.\r\nfor project_name in project_names:\r\n    if plan_by_project.get(project_name):\r\n        continue\r\n    pr = project_map.get(project_name) or {}\r\n    executive_data.append({\r\n        "project":project_name,"project_name":pr.get("project_name") or project_name,\r\n        "project_stage":pr.get("custom_project_stage") or "","project_health":pr.get("custom_calculated_project_health") or "",\r\n        "project_manager":pr.get("custom_project_manager") or "","plan":"","plan_status":"Not Planned",\r\n        "tracking_mode":pr.get("custom_beneficiary_tracking_mode") or "",\r\n        "donors":", ".join(project_donor_values.get(project_name) or []),\r\n        "sectors":", ".join(project_sector_values.get(project_name) or []),\r\n        "implementing_partners":", ".join(project_partner_values.get(project_name) or []),\r\n        "governorate":", ".join(project_governorate_context.get(project_name) or []),\r\n        "district":", ".join(project_district_context.get(project_name) or []),\r\n        "planned_individuals":0,"actual_individuals":0,"individual_variance":0,"individual_achievement":0,\r\n        "planned_households":0,"actual_households":0,"household_variance":0,"household_achievement":0,\r\n        "planned_pwd":0,"actual_pwd":0,"pwd_achievement":0,"actual_update_frequency":"","last_actual_update":None,\r\n        "actuals_finalized":0,"reach_status":"Not Planned","data_quality_status":"Not Planned",\r\n        "quality_flags":"Beneficiary Plan Not Available","beneficiary_attention":"Review Required"\r\n    })\r\n\r\n# Select columns and rows by view.\r\nbase_exec = [\r\n {"label":_("Project"),"fieldname":"project","fieldtype":"Link","options":"Project","width":150},\r\n {"label":_("Project Name"),"fieldname":"project_name","fieldtype":"Data","width":220},\r\n {"label":_("Stage"),"fieldname":"project_stage","fieldtype":"Data","width":130},\r\n {"label":_("Plan"),"fieldname":"plan","fieldtype":"Link","options":"Project Beneficiary Plan","width":170},\r\n {"label":_("Plan Status"),"fieldname":"plan_status","fieldtype":"Data","width":130},\r\n {"label":_("Tracking Mode"),"fieldname":"tracking_mode","fieldtype":"Data","width":130},\r\n {"label":_("Donors"),"fieldname":"donors","fieldtype":"Data","width":180},\r\n {"label":_("Sectors"),"fieldname":"sectors","fieldtype":"Data","width":160},\r\n {"label":_("Partners"),"fieldname":"implementing_partners","fieldtype":"Data","width":170},\r\n {"label":_("Governorates"),"fieldname":"governorate","fieldtype":"Data","width":150},\r\n {"label":_("Districts"),"fieldname":"district","fieldtype":"Data","width":160},\r\n {"label":_("Planned Individuals"),"fieldname":"planned_individuals","fieldtype":"Int","width":130},\r\n {"label":_("Actual Individuals"),"fieldname":"actual_individuals","fieldtype":"Int","width":125},\r\n {"label":_("Reach %"),"fieldname":"individual_achievement","fieldtype":"Percent","width":90},\r\n {"label":_("Variance"),"fieldname":"individual_variance","fieldtype":"Int","width":90},\r\n {"label":_("Planned Households"),"fieldname":"planned_households","fieldtype":"Int","width":130},\r\n {"label":_("Actual Households"),"fieldname":"actual_households","fieldtype":"Int","width":125},\r\n {"label":_("HH Reach %"),"fieldname":"household_achievement","fieldtype":"Percent","width":95},\r\n {"label":_("Planned PWD"),"fieldname":"planned_pwd","fieldtype":"Int","width":105},\r\n {"label":_("Actual PWD"),"fieldname":"actual_pwd","fieldtype":"Int","width":100},\r\n {"label":_("Last Actual Update"),"fieldname":"last_actual_update","fieldtype":"Datetime","width":145},\r\n {"label":_("Finalized"),"fieldname":"actuals_finalized","fieldtype":"Check","width":80},\r\n {"label":_("Reach Status"),"fieldname":"reach_status","fieldtype":"Data","width":125},\r\n {"label":_("Data Quality"),"fieldname":"data_quality_status","fieldtype":"Data","width":110},\r\n {"label":_("Quality Flags"),"fieldname":"quality_flags","fieldtype":"Data","width":260},\r\n {"label":_("Attention"),"fieldname":"beneficiary_attention","fieldtype":"Data","width":135}\r\n]\r\ncommon_detail = [\r\n {"label":_("Project"),"fieldname":"project","fieldtype":"Link","options":"Project","width":150},\r\n {"label":_("Plan"),"fieldname":"plan","fieldtype":"Link","options":"Project Beneficiary Plan","width":165},\r\n {"label":_("Row Code"),"fieldname":"row_code","fieldtype":"Data","width":100},\r\n {"label":_("Reporting Period"),"fieldname":"reporting_period","fieldtype":"Data","width":130},\r\n {"label":_("From"),"fieldname":"period_from","fieldtype":"Date","width":95},\r\n {"label":_("To"),"fieldname":"period_to","fieldtype":"Date","width":95},\r\n {"label":_("Result"),"fieldname":"result_title","fieldtype":"Data","width":240},\r\n {"label":_("Activity"),"fieldname":"activity_title","fieldtype":"Data","width":250},\r\n {"label":_("Indicator"),"fieldname":"indicator_title","fieldtype":"Data","width":220},\r\n {"label":_("Sector"),"fieldname":"sector","fieldtype":"Data","width":145},\r\n {"label":_("Donors"),"fieldname":"donors","fieldtype":"Data","width":170},\r\n {"label":_("Partner"),"fieldname":"implementing_partner","fieldtype":"Link","options":"Supplier","width":150},\r\n {"label":_("Location"),"fieldname":"geographic_location","fieldtype":"Link","options":"Project Geographic Location","width":165},\r\n {"label":_("Governorate"),"fieldname":"governorate","fieldtype":"Data","width":115},\r\n {"label":_("District"),"fieldname":"district","fieldtype":"Data","width":115},\r\n {"label":_("Reach Type"),"fieldname":"reach_type","fieldtype":"Data","width":90},\r\n {"label":_("Counting Method"),"fieldname":"counting_method","fieldtype":"Data","width":145},\r\n {"label":_("Primary Unit"),"fieldname":"primary_unit","fieldtype":"Data","width":115},\r\n {"label":_("Planned Individuals"),"fieldname":"planned_individuals","fieldtype":"Int","width":120},\r\n {"label":_("Actual Individuals"),"fieldname":"actual_individuals","fieldtype":"Int","width":115},\r\n {"label":_("Reach %"),"fieldname":"individual_achievement","fieldtype":"Percent","width":90},\r\n {"label":_("Planned HH"),"fieldname":"planned_households","fieldtype":"Int","width":95},\r\n {"label":_("Actual HH"),"fieldname":"actual_households","fieldtype":"Int","width":90},\r\n {"label":_("HH Reach %"),"fieldname":"household_achievement","fieldtype":"Percent","width":95},\r\n {"label":_("Data Quality"),"fieldname":"data_quality","fieldtype":"Data","width":145},\r\n {"label":_("Quality Flags"),"fieldname":"quality_flags","fieldtype":"Data","width":250}\r\n]\r\ncolumns = base_exec\r\nrows = executive_data\r\nif view in ["Demographic","Geographic","Sector","Partner","Period Performance","Full"]:\r\n    rows = detail_data\r\n    columns = common_detail\r\nif view == "Demographic":\r\n    columns = common_detail[:16] + [\r\n     {"label":_("Planned Women 18+"),"fieldname":"planned_women","fieldtype":"Int","width":120},\r\n     {"label":_("Actual Women 18+"),"fieldname":"actual_women","fieldtype":"Int","width":115},\r\n     {"label":_("Planned Men 18+"),"fieldname":"planned_men","fieldtype":"Int","width":110},\r\n     {"label":_("Actual Men 18+"),"fieldname":"actual_men","fieldtype":"Int","width":105},\r\n     {"label":_("Planned Girls <18"),"fieldname":"planned_girls","fieldtype":"Int","width":115},\r\n     {"label":_("Actual Girls <18"),"fieldname":"actual_girls","fieldtype":"Int","width":110},\r\n     {"label":_("Planned Boys <18"),"fieldname":"planned_boys","fieldtype":"Int","width":115},\r\n     {"label":_("Actual Boys <18"),"fieldname":"actual_boys","fieldtype":"Int","width":110},\r\n     {"label":_("Planned PWD"),"fieldname":"planned_pwd","fieldtype":"Int","width":100},\r\n     {"label":_("Actual PWD"),"fieldname":"actual_pwd","fieldtype":"Int","width":95},\r\n     {"label":_("Planned Female-Headed HH"),"fieldname":"planned_female_headed_hh","fieldtype":"Int","width":150},\r\n     {"label":_("Actual Female-Headed HH"),"fieldname":"actual_female_headed_hh","fieldtype":"Int","width":145},\r\n     {"label":_("Planned Older Persons"),"fieldname":"planned_older_persons","fieldtype":"Int","width":140},\r\n     {"label":_("Actual Older Persons"),"fieldname":"actual_older_persons","fieldtype":"Int","width":135},\r\n     {"label":_("Displacement Status"),"fieldname":"displacement_status","fieldtype":"Data","width":135},\r\n     {"label":_("Population Group"),"fieldname":"population_group","fieldtype":"Data","width":140},\r\n     {"label":_("Beneficiary Category"),"fieldname":"beneficiary_category","fieldtype":"Data","width":150},\r\n     {"label":_("Data Quality"),"fieldname":"data_quality","fieldtype":"Data","width":140},\r\n     {"label":_("Quality Flags"),"fieldname":"quality_flags","fieldtype":"Data","width":240}\r\n    ]\r\nif view == "Full":\r\n    columns = common_detail + [\r\n     {"label":_("Planned Women"),"fieldname":"planned_women","fieldtype":"Int","width":100},\r\n     {"label":_("Planned Men"),"fieldname":"planned_men","fieldtype":"Int","width":95},\r\n     {"label":_("Planned Girls"),"fieldname":"planned_girls","fieldtype":"Int","width":95},\r\n     {"label":_("Planned Boys"),"fieldname":"planned_boys","fieldtype":"Int","width":95},\r\n     {"label":_("Actual Women"),"fieldname":"actual_women","fieldtype":"Int","width":100},\r\n     {"label":_("Actual Men"),"fieldname":"actual_men","fieldtype":"Int","width":95},\r\n     {"label":_("Actual Girls"),"fieldname":"actual_girls","fieldtype":"Int","width":95},\r\n     {"label":_("Actual Boys"),"fieldname":"actual_boys","fieldtype":"Int","width":95},\r\n     {"label":_("Planned Other Units"),"fieldname":"planned_other_units","fieldtype":"Int","width":125},\r\n     {"label":_("Actual Other Units"),"fieldname":"actual_other_units","fieldtype":"Int","width":120},\r\n     {"label":_("Planned PWD"),"fieldname":"planned_pwd","fieldtype":"Int","width":95},\r\n     {"label":_("Actual PWD"),"fieldname":"actual_pwd","fieldtype":"Int","width":90},\r\n     {"label":_("Tracking Method"),"fieldname":"tracking_method","fieldtype":"Data","width":120},\r\n     {"label":_("Data Source"),"fieldname":"data_source","fieldtype":"Data","width":170},\r\n     {"label":_("Variance Explanation"),"fieldname":"variance_explanation","fieldtype":"Data","width":240},\r\n     {"label":_("Notes"),"fieldname":"notes","fieldtype":"Data","width":220}\r\n    ]\r\n\r\n# Summary uses authoritative plan totals and never mixes people with households.\r\ntotal_pi=0; total_ai=0; total_ph=0; total_ah=0; total_pwd=0; below=0; issues=0; finalized=0\r\nfor r in executive_data:\r\n    total_pi += int(r.get("planned_individuals") or 0); total_ai += int(r.get("actual_individuals") or 0)\r\n    total_ph += int(r.get("planned_households") or 0); total_ah += int(r.get("actual_households") or 0)\r\n    total_pwd += int(r.get("actual_pwd") or 0)\r\n    if r.get("reach_status")=="Below Target": below += 1\r\n    if r.get("data_quality_status")=="Issue": issues += 1\r\n    if int(r.get("actuals_finalized") or 0)==1: finalized += 1\r\nreport_summary = [\r\n {"value":len(executive_data),"label":_("Projects with Plans"),"indicator":"Blue"},\r\n {"value":total_pi,"label":_("Planned Individuals"),"indicator":"Blue"},\r\n {"value":total_ai,"label":_("Actual Individuals"),"indicator":"Green"},\r\n {"value":(float(total_ai)*100.0/float(total_pi)) if total_pi>0 else 0,"label":_("Overall Individual Reach %"),"datatype":"Percent","indicator":"Green"},\r\n {"value":total_ph,"label":_("Planned Households"),"indicator":"Blue"},\r\n {"value":total_ah,"label":_("Actual Households"),"indicator":"Green"},\r\n {"value":total_pwd,"label":_("Actual PWD"),"indicator":"Purple"},\r\n {"value":finalized,"label":_("Finalized Plans"),"indicator":"Green"},\r\n {"value":below,"label":_("Projects Below Target"),"indicator":"Orange"},\r\n {"value":issues,"label":_("Data Quality Issues"),"indicator":"Red"}\r\n]\r\nchart = {"data":{"labels":[_("Below Target"),_("On Track"),_("Target Achieved"),_("Exceeded Target"),_("Not Reported")],"datasets":[{"name":_("Projects"),"values":[0,0,0,0,0]}]},"type":"donut"}\r\nfor r in executive_data:\r\n    s=r.get("reach_status")\r\n    if s=="Below Target": chart["data"]["datasets"][0]["values"][0]=chart["data"]["datasets"][0]["values"][0]+1\r\n    elif s=="On Track": chart["data"]["datasets"][0]["values"][1]=chart["data"]["datasets"][0]["values"][1]+1\r\n    elif s=="Target Achieved": chart["data"]["datasets"][0]["values"][2]=chart["data"]["datasets"][0]["values"][2]+1\r\n    elif s=="Exceeded Target": chart["data"]["datasets"][0]["values"][3]=chart["data"]["datasets"][0]["values"][3]+1\r\n    elif s=="Not Reported": chart["data"]["datasets"][0]["values"][4]=chart["data"]["datasets"][0]["values"][4]+1\r\nmessage = _("Executive totals use submitted Project Beneficiary Plan summaries; when a detail dimension or date filter is active, totals are recalculated from matching Breakdown rows. Detail views use Beneficiary Breakdown rows. Activity Reach, Service Contacts, and Indirect Reach are not treated as unique people; review Quality Flags before aggregation.")\r\ndata = (columns, rows, message, chart, report_summary, 1)\r\n'
def _apply_native_sticky(result):
    if not result:
        return result
    values = list(result) if isinstance(result, (tuple, list)) else [result]
    if not values:
        return result
    columns = values[0] or []
    for index, column in enumerate(columns):
        if isinstance(column, dict):
            column["sticky"] = bool(index < 2)
    values[0] = columns
    return tuple(values)

def execute(filters=None):
    local_vars={"filters":filters or {}}
    safe_exec(REPORT_SCRIPT,None,local_vars,script_filename='Beneficiary Reach')
    return finalize_report_result(local_vars.get("data") or ([], []))
